diff --git a/src/config.js b/src/config.js
index 726fdca..792e7a8 100644
--- a/src/config.js
+++ b/src/config.js
@@ -1,7 +1,29 @@
+function isPlainObject(value) {
+	return value !== null && typeof value === "object" && Object.getPrototypeOf(value) === Object.prototype;
+}
+
 /**
- * Returns the configuration `defaults` with `overrides` applied: each key of `overrides` replaces the default value.
+ * Returns the configuration `defaults` with `overrides` applied.
+ * Nested plain objects are merged key by key; other override values replace defaults.
  * Neither argument is modified.
  */
 export function mergeConfig(defaults, overrides) {
-	return { ...defaults, ...overrides };
+	const result = { ...defaults, ...overrides };
+
+	for (const key of Reflect.ownKeys(Object(overrides))) {
+		if (!Object.prototype.propertyIsEnumerable.call(overrides, key)) continue;
+
+		const defaultValue = defaults?.[key];
+		const overrideValue = result[key];
+		if (isPlainObject(defaultValue) && isPlainObject(overrideValue)) {
+			Object.defineProperty(result, key, {
+				value: mergeConfig(defaultValue, overrideValue),
+				enumerable: true,
+				configurable: true,
+				writable: true,
+			});
+		}
+	}
+
+	return result;
 }
diff --git a/test/config.test.js b/test/config.test.js
index 0ef0b7d..863c74d 100644
--- a/test/config.test.js
+++ b/test/config.test.js
@@ -17,3 +17,39 @@ test("nested objects merge key by key", () => {
 		level: "info",
 	});
 });
+
+test("plain objects merge at multiple depths without modifying inputs", () => {
+	const defaults = Object.freeze({
+		server: Object.freeze({
+			host: "localhost",
+			tls: Object.freeze({ enabled: true, port: 443 }),
+		}),
+	});
+	const overrides = Object.freeze({
+		server: Object.freeze({ tls: Object.freeze({ port: 8443 }) }),
+	});
+	const result = mergeConfig(defaults, overrides);
+	assert.deepEqual(result, {
+		server: { host: "localhost", tls: { enabled: true, port: 8443 } },
+	});
+	assert.notEqual(result.server, defaults.server);
+	assert.notEqual(result.server.tls, defaults.server.tls);
+	assert.notEqual(result.server.tls, overrides.server.tls);
+});
+
+test("non-object overrides replace nested defaults whole", () => {
+	for (const value of [["c"], null, "disabled", 0, false, undefined]) {
+		assert.deepEqual(mergeConfig({ setting: { enabled: true } }, { setting: value }), {
+			setting: value,
+		});
+	}
+	assert.deepEqual(mergeConfig({ tags: ["a", "b"] }, { tags: ["c"] }), { tags: ["c"] });
+});
+
+test("plain object overrides replace non-object defaults", () => {
+	for (const value of [null, [1, 2], "text", 42]) {
+		assert.deepEqual(mergeConfig({ setting: value }, { setting: { enabled: true } }), {
+			setting: { enabled: true },
+		});
+	}
+});

diff --git a/src/config.js b/src/config.js
index 726fdca..9706f58 100644
--- a/src/config.js
+++ b/src/config.js
@@ -1,7 +1,24 @@
+function isPlainObject(value) {
+	return value !== null && typeof value === "object" && Object.getPrototypeOf(value) === Object.prototype;
+}
+
 /**
- * Returns the configuration `defaults` with `overrides` applied: each key of `overrides` replaces the default value.
+ * Returns the configuration `defaults` with `overrides` applied.
+ * Nested plain objects merge key by key; other override values replace defaults.
  * Neither argument is modified.
  */
 export function mergeConfig(defaults, overrides) {
-	return { ...defaults, ...overrides };
+	const result = { ...defaults, ...overrides };
+	for (const key of Reflect.ownKeys(result)) {
+		if (
+			defaults != null && overrides != null &&
+			Object.prototype.propertyIsEnumerable.call(overrides, key) &&
+			Object.prototype.propertyIsEnumerable.call(defaults, key) &&
+			isPlainObject(defaults[key]) &&
+			isPlainObject(overrides[key])
+		) {
+			result[key] = mergeConfig(defaults[key], overrides[key]);
+		}
+	}
+	return result;
 }
